-- AD8 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD8.sql.
SELECT 'bound-session columns exist on the session table' AS rule, (SELECT count(*) FROM information_schema.columns WHERE table_schema='desk' AND table_name='fadm_session' AND column_name IN ('dbsc_key','dbsc_registered_at','dbsc_last_refresh_at')) = 3 AS ok
UNION ALL SELECT 'the device key is frozen by a trigger', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='desk.fadm_session'::regclass AND tgname='fadm_session_00dbsc_frozen')
UNION ALL SELECT 'the key shape is a constraint (EC P-256 only)', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='desk.fadm_session'::regclass AND conname='fadm_session_dbsc_key_shape')
UNION ALL SELECT 'the proof-id table has forced RLS and desk_app has no right on it', (SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='desk.fadm_dbsc_jti'::regclass) AND NOT has_table_privilege('desk_app','desk.fadm_dbsc_jti','select')
UNION ALL SELECT 'the five public doors are granted to desk_app', has_function_privilege('desk_app','desk.fadm_dbsc_register(bytea,jsonb,text)','execute') AND has_function_privilege('desk_app','desk.fadm_dbsc_key(bytea)','execute') AND has_function_privilege('desk_app','desk.fadm_dbsc_refresh(bytea,text)','execute') AND has_function_privilege('desk_app','desk.fadm_dbsc_refuse(bytea,text,text)','execute') AND has_function_privilege('desk_app','desk.fadm_dbsc_status(bytea)','execute')
UNION ALL SELECT 'the two internal helpers are NOT callable by desk_app or PUBLIC', NOT has_function_privilege('desk_app','desk.fadm_dbsc_consume(uuid,text)','execute') AND NOT has_function_privilege('public','desk.fadm_dbsc_live(bytea)','execute')
UNION ALL SELECT 'all doors are SECURITY DEFINER', (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='desk' AND p.proname LIKE 'fadm_dbsc_%' AND p.prosecdef) = 7
UNION ALL SELECT 'the four DBSC ledger kinds are on the closed list', (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('dbsc.registered','dbsc.refreshed','dbsc.refused','ad8.selftest')) = 4
UNION ALL SELECT 'the hash chain still verifies', desk.fadm_ledger_verify();
